div.script:
(function () {
    function toggleGroups(selectEl) {
        var persona = (selectEl && selectEl.value) || 'clinica';
        var groups = document.querySelectorAll('.js-bader-profile-group');
        for (var i = 0; i < groups.length; i += 1) {
            var node = groups[i];
            var target = (node.getAttribute('data-persona-group') || '').split(',');
            var visible = target.indexOf(persona) !== -1;
            node.style.display = visible ? '' : 'none';
        }
    }

    document.addEventListener('DOMContentLoaded', function () {
        var selectEl = document.querySelector('[data-bader-persona-select="1"]');
        if (!selectEl) {
            return;
        }
        toggleGroups(selectEl);
        selectEl.addEventListener('change', function () {
            toggleGroups(selectEl);
        });
    });
})();
